            v.submodule_index().* = 10;
            v.subsubmodule_index().* = 0;
        }
        v.dung_num_lit_torches().* += 1;
    }

    v.dung_torch_timers()[v.byte_7E0333().* & 0xf] = r8;
    v.byte_7E0333().* = 0;
}

pub export fn RoomDraw_AdjustTorchLightingChange(x: t.uint16, y: t.uint16, r8: t.uint16) void { // 81f746
